  <script>
    const inputs = [...document.querySelectorAll("#codeInputs input")];
    const verifyButton = document.getElementById("verifyButton");
    const countdownButton = document.getElementById("countdown");
    let seconds = 45;
    let timer;

    function updateButton() {
      verifyButton.disabled = inputs.some(input => !input.value);
    }

    function moveFocus(index, direction = 1) {
      if (index < 0 || index >= inputs.length) return;
      inputs[index].focus();
      inputs[index].select();
    }

    inputs.forEach((input, index) => {
      input.addEventListener("input", () => {
        input.value = input.value.replace(/\D/g, "").slice(-1);
        if (input.value && index < inputs.length - 1) {
          moveFocus(index + 1);
        }
        updateButton();
      });

      input.addEventListener("keydown", event => {
        if (event.key === "Backspace" && !input.value && index > 0) {
          moveFocus(index - 1, -1);
        } else if (event.key === "ArrowLeft" && index < inputs.length - 1) {
          moveFocus(index + 1);
        } else if (event.key === "ArrowRight" && index > 0) {
          moveFocus(index - 1, -1);
        }
      });

      input.addEventListener("paste", event => {
        const digits = event.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
        if (digits) {
          event.preventDefault();
          inputs.forEach((field, fieldIndex) => {
            field.value = digits[fieldIndex] || "";
          });
          moveFocus(Math.min(digits.length, inputs.length - 1));
          updateButton();
        }
      });
    });

    function startCountdown() {
      clearInterval(timer);
      seconds = 45;
      countdownButton.textContent = "0:45";

      timer = setInterval(() => {
        seconds--;
        countdownButton.textContent = `0:${String(seconds).padStart(2, "0")}`;

        if (seconds <= 0) {
          clearInterval(timer);
          countdownButton.textContent = "إعادة الإرسال الآن";
          countdownButton.style.cursor = "pointer";
        }
      }, 1000);
    }

    countdownButton.addEventListener("click", () => {
      if (seconds <= 0) startCountdown();
    });

    document.getElementById("codeForm").addEventListener("submit", event => {
      event.preventDefault();
      if (!verifyButton.disabled) {
        verifyButton.textContent = "جارٍ التحقق...";
        verifyButton.disabled = true;
      }
    });

    updateButton();
    startCountdown();
    inputs[0].focus();
  </script>
